from collections import defaultdict


class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.limit_bytes: float = monthly_limit_mib * 1024 * 1024
        # Stores files per month: month -> {filename: size_bytes}
        self.files: dict[str, dict[str, int]] = defaultdict(dict)

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like '2026-01'."""
        if size_bytes <= 0:
            raise ValueError("File size must be greater than 0 bytes.")

        month_files = self.files[month]

        # If the file already exists in this month with the exact same name,
        # it does not count towards the limit a second time.
        if name in month_files:
            return

        current_used = sum(month_files.values())
        if current_used + size_bytes > self.limit_bytes:
            raise ValueError("Upload exceeds monthly quota limit.")

        month_files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        month_files = self.files[month]
        if name in month_files:
            del month_files[name]

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return sum(self.files[month].values())
